#!/usr/bin/env bash
# Timing and size of `ay` binaries built by different LLVM variants (docs/native/BUILD-SCIENCE.md, table generated by
# scripts/bench/llvm-table.ts). Run it on a quiet host (fr2), never on a loaded one: hyperfine reports the load in
# `load` of the output so a noisy run is visible.
#   llvm-bench.sh <outdir> <corpus-dir> <variant>=<binary> [<variant>=<binary> ...]
# Writes <outdir>/<variant>.<scenario>.json (hyperfine) and <outdir>/sizes.json ({variant: {file, stripped}}).
# Scenarios: start (`ay --version`, cold start), graph (tree-sitter code graph of the corpus), ingest (outline digest
# of the corpus), hash (wyhash of the largest file of the corpus). Binaries are stripped copies for timing and size.
set -eu
out=$1 corpus=$2
shift 2
mkdir -p "$out"
work=$(mktemp -d)
big=$(find "$corpus" -type f -printf '%s %p\n' | sort -nr | head -n 1 | cut -d' ' -f2-)
printf '{' > "$out/sizes.json"
sep=
for spec in "$@"; do
	v=${spec%%=*} bin=${spec#*=}
	cp "$bin" "$work/$v.full"
	llvm-strip -o "$work/$v" "$work/$v.full" 2>/dev/null || strip -o "$work/$v" "$work/$v.full"
	printf '%s"%s":{"file":%s,"stripped":%s}' "$sep" "$v" "$(stat -c %s "$work/$v.full")" "$(stat -c %s "$work/$v")" >> "$out/sizes.json"
	sep=,
	rm -f "$work/$v.full"
	mkdir -p "$work/cwd-$v"
	hyperfine -N --warmup 5 --runs 60 --export-json "$out/$v.start.json" "$work/$v --version" > /dev/null
	hyperfine --warmup 2 --runs 20 --export-json "$out/$v.graph.json" "cd $work/cwd-$v && $work/$v graph build $corpus" > /dev/null
	hyperfine --warmup 2 --runs 20 --export-json "$out/$v.ingest.json" "$work/$v ingest --outline -o /dev/null $corpus" > /dev/null
	hyperfine -N --warmup 2 --runs 20 --export-json "$out/$v.hash.json" "$work/$v hash $big" > /dev/null
done
printf '}\n' >> "$out/sizes.json"
uptime | sed 's/.*load average: //' > "$out/load.txt"
rm -rf "$work"
